"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["22302"],{16602(e){e.exports=JSON.parse('{"id":"FIN-828","slug":"credit-bureau","term":"Credit Bureau","also_known_as":[],"difficulty":"Beginner","definition":"A credit bureau is a company that collects and maintains information about how individuals and businesses borrow and repay money, and provides credit reports and credit scores to lenders and other authorised users.","explanation":["Credit bureaus, also called credit reference agencies, gather information from lenders, such as banks, credit card companies and utility providers, as well as some public records. They use this information to build a credit file for each person.","A credit file typically shows the accounts a person holds, their credit limits and balances, their payment history, any missed payments or defaults and recent applications for credit.","When someone applies for a loan, mortgage, credit card or even a rental property or phone contract, the lender usually checks their credit report from one or more bureaus to judge how likely they are to repay.","Major credit bureaus include Equifax, Experian and TransUnion, which operate in many countries, although some countries have different or state-run systems. Individuals generally have the right to see their credit reports and to correct inaccurate information. Checking your report regularly can help spot errors or signs of identity fraud."],"note":"","total":1500,"prev":{"slug":"credit-analysis","term":"Credit Analysis"},"next":{"slug":"credit-card","term":"Credit Card"}}')}}]);